candidates.raw:
    size_t i;
    unint32 mask = 0U;
    adcs_vec3_t achieved = {0.0, 0.0, 0.0};
    double u[3];
    const double tol = 1.0e-10;

    /* NULL 检查优先于所有数值检查 */
    if ((wheel_axes_body == NULL) || (desired_body_torque_nm == NULL) ||
        (wheel_torque_limit_nm == NULL) || (wheel_torque_nm == NULL) ||
        (achieved_body_torque_nm == NULL) || (saturation_mask == NULL)) {
        if (wheel_torque_nm != NULL) {
            wheel_torque_nm[0] = 0.0;
            wheel_torque_nm[1] = 0.0;
            wheel_torque_nm[2] = 0.0;
        }
        if (achieved_body_torque_nm != NULL) {
            achieved_body_torque_nm->x = 0.0;
            achieved_body_torque_nm->y = 0.0;
            achieved_body_torque_nm->z = 0.0;
        }
        if (saturation_mask != NULL) {
            *saturation_mask = 0U;
        }
        return ADCS_E_NULL;
    }

    /* desired torque 有限性 */
    if (!adcs_is_finite_vec3(desired_body_torque_nm))
        goto range_fail;

    /* 三元组：有限、单位模长（1e-10 容差）、两两正交（1e-10 容差） */
    for (i = 0; i < 3U; i++) {
        double n;
        if (!adcs_is_finite_vec3(&wheel_axes_body[i]))
            goto range_fail;
        n = adcs_vec3_norm(&wheel_axes_body[i]);
        if (!isfinite(n) || (fabs(n - 1.0) > tol))
            goto range_fail;
    }
    {
        double d01 = adcs_vec3_dot(&wheel_axes_body[0], &wheel_axes_body[1]);
        double d02 = adcs_vec3_dot(&wheel_axes_body[0], &wheel_axes_body[2]);
        double d12 = adcs_vec3_dot(&wheel_axes_body[1], &wheel_axes_body[2]);
        if ((fabs(d01) > tol) || (fabs(d02) > tol) || (fabs(d12) > tol))
            goto range_fail;
    }

    /* 三个 limit：有限且非负 */
    for (i = 0; i < 3U; i++) {
        if (!isfinite(wheel_torque_limit_nm[i]) || (wheel_torque_limit_nm[i] < 0.0))
            goto range_fail;
    }

    /* 逐轮分配：u_i = -a_i · tau_desired */
    for (i = 0; i < 3U; i++) {
        u[i] = -adcs_vec3_dot(&wheel_axes_body[i], desired_body_torque_nm);
    }

    /* 逐轮对称限幅，被钳位者置 mask 位 i */
    for (i = 0; i < 3U; i++) {
        double lim = wheel_torque_limit_nm[i];
        if (u[i] > lim) {
            u[i] = lim;
            mask |= (unint32)(1U << i);
